1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type Project = { id: number; name: string; clientId: number; clientName: string };
11	type Invoice = {
12	  id: number;
13	  projectId: number;
14	  amount: number;
15	  status: string;
16	  issuedDate: string;
17	  dueDate: string;
18	};
19	
20	function money(amount: number): string {
21	  return `$${Number(amount).toFixed(2)}`;
22	}
23	
24	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
25	// own invoice state, scoped to the one project it is showing.
26	function ProjectDetail({ project }: { project: Project }) {
27	  const [invoices, setInvoices] = useState<Invoice[]>([]);
28	  const [amount, setAmount] = useState('');
29	  const [amountError, setAmountError] = useState('');
30	  const [sortByDue, setSortByDue] = useState(false);
31	
32	  async function load() {
33	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
34	    setInvoices(await res.json());
35	  }
36	
37	  useEffect(() => {
38	    void load();
39	  }, [project.id]);
40	
41	  async function submit(e: React.FormEvent) {
42	    e.preventDefault();
43	    const value = Number(amount);
44	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
45	      setAmountError('Amount must be more than zero');
46	      return;
47	    }
48	    setAmountError('');
49	    await fetch('/api/invoices', {
50	      method: 'POST',
51	      headers: { 'Content-Type': 'application/json' },
52	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
53	    });
54	    setAmount('');
55	    await load();
56	  }
57	
58	  async function send(id: number) {
59	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
60	    await load();
61	  }
62	
63	  async function pay(id: number) {
64	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
65	    await load();
66	  }
67	
68	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
69	  const shownInvoices = sortByDue
70	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
71	    : invoices;
72	
73	  return (
74	    <section data-testid="project-detail">
75	      <h2 data-testid="project-detail-name">{project.name}</h2>
76	
77	      <form data-testid="invoice-form" onSubmit={submit}>
78	        <input
79	          data-testid="invoice-form-amount"
80	          placeholder="Amount"
81	          value={amount}
82	          onChange={(e) => setAmount(e.target.value)}
83	        />
84	        <button data-testid="invoice-form-submit" type="submit">
85	          Add invoice
86	        </button>
87	        {amountError && (
88	          <p data-testid="invoice-form-amount-error" role="alert">
89	            {amountError}
90	          </p>
91	        )}
92	      </form>
93	
94	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
95	        Sort by due date
96	      </button>
97	
98	      <table data-testid="project-invoices-table">
99	        <tbody>
100	          {shownInvoices.map((inv) => (
101	            <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
102	              <td data-testid="invoice-amount">{money(inv.amount)}</td>
103	              <td data-testid="invoice-issued">{inv.issuedDate}</td>
104	              <td data-testid="invoice-due">{inv.dueDate}</td>
105	              <td data-testid="invoice-status">{inv.status}</td>
